-- Programa oficial por (edital, matéria) — P1 do diagnóstico de 03/08.
-- `topicos_curados` é um booleano sem lastro: afirma que a lista de tópicos
-- foi conferida, mas não guarda CONTRA O QUÊ. Esta tabela guarda o texto
-- verbatim do conteúdo programático oficial (Anexo II), com fonte e data:
--   - o aluno confere o programa oficial na própria página do edital;
--   - retificação vira diff de texto, não re-curadoria do zero;
--   - o mapeamento item→tópico (fase 2 do P1) nasce por cima disto.
-- Texto extraído por script dos mesmos PDFs oficiais da curadoria
-- (pdftotext -raw, Anexos II retificados de 12/05/2022) — não digitado à mão.
-- QOS 2º Tenente (médicos, Edital 003) fora: cargos não existem no catálogo.

create table public.edital_programas (
  edital_catalog_id  uuid not null references public.editais_catalog(id) on delete cascade,
  subject_catalog_id uuid not null references public.subjects_catalog(id) on delete cascade,
  texto        text not null,
  fonte_url    text,
  conferido_em date,
  primary key (edital_catalog_id, subject_catalog_id)
);

comment on table public.edital_programas is
  'Conteúdo programático oficial (verbatim do edital/anexo) por matéria. Fonte da verdade da curadoria de tópicos por edital.';

alter table public.edital_programas enable row level security;
create policy "catalog_read_edital_programas" on public.edital_programas
  for select to authenticated using (true);
create policy "read edital_programas anon" on public.edital_programas
  for select to anon using (true);

insert into public.edital_programas (edital_catalog_id, subject_catalog_id, texto, fonte_url, conferido_em)
select e.id, s.id, v.texto, v.fonte_url, '2026-08-03'
from (values
  ('pm-go-soldado', 'Língua Portuguesa', '1. Compreensão e interpretação de texto. 2. Tipologia e gêneros textuais. 3. Figuras de linguagem. 4. Significação de palavras e expressões. 5. Relações de sinonímia e de antonímia. 6. Ortografia. 7. Acentuação gráfica. 8. Uso da crase. 9. Morfologia: classes de palavras variáveis e invariáveis e seus empregos no texto. 10. Locuções verbais (perífrases verbais). 11. Funções do "que" e do "se". 12. Elementos de comunicação e funções da linguagem. 13. Domínio dos mecanismos de coesão textual: emprego de elementos de referenciação, substituição e repetição, de conectores e de outros elementos de sequenciação textual; emprego de tempos e modos verbais. 14. Domínio dos mecanismos de coerência textual. 15. Reescrita de frases e parágrafos do texto: significação das palavras; substituição de palavras ou de trechos de texto; reorganização da estrutura de orações e de períodos do texto; reescrita de textos de diferentes gêneros e níveis de formalidade. 16. Sintaxe: relações sintático-semânticas estabelecidas na oração e entre orações, períodos ou parágrafos (período simples e período composto por coordenação e subordinação). 17. Concordância verbal e nominal. 18. Regência verbal e nominal. 19. Colocação pronominal. 20. Emprego dos sinais de pontuação e sua função no texto. 21. Função textual dos vocábulos. Variação linguística. 22. Redação Oficial.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Conhecimentos Regionais', '1. Formação econômica de Goiás: a mineração no século XVIII, a agropecuária nos séculos XIX e XX, a estrada de ferro e a modernização da economia goiana, as transformações econômicas com a construção de Goiânia e Brasília, industrialização, infraestrutura e planejamento. 2. Aspectos físicos do território goiano: vegetação, hidrografia, clima e relevo. 3. Aspectos da história política de Goiás: os bandeirantes e a colonização, o coronelismo e oligarquia na República Velha, a Revolução de 1930, aspectos políticos e administrativos de 1930 até os dias atuais. 4. Aspectos da História Sociocultural de Goiás: o povoamento branco, os grupos indígenas, a escravidão e cultura negra, os movimentos sociais no campo e a cultura popular goiana. 5. Atualidades econômicas, políticas, sociais e culturais do Brasil do Estado de Goiás.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Penal', 'Direito Penal: 1. Aplicação da lei penal. 1.1. Princípios da legalidade e da anterioridade. 1.2 A lei penal no tempo e no espaço. 1.3 Tempo e lugar do crime. 1.4. Lei penal excepcional, especial e temporária. 1.5. Territorialidade e extraterritorialidade da lei penal. 1.6. Pena cumprida no estrangeiro. 1.7. Eficácia da sentença estrangeira. 1.8. Contagem de prazo. 1.9. Frações não computáveis da pena. 1.10. Interpretação da lei penal. 1.11. Analogia. 1.12. Irretroatividade da lei penal. 1.13. Conflito aparente de normas penais. 2. Crimes contra a pessoa. 3. Crimes contra o patrimônio. 4. Crimes contra a administração pública. 5. Disposições constitucionais aplicáveis ao direito penal. 6. Lei Maria da Penha (Lei federal nº 11.340/2006, arts. 01a 07).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Constitucional', '1. Dos princípios fundamentais. 1.1. Dos direitos e garantias fundamentais (direitos e deveres individuais e coletivos, nacionalidade). 1.2. Da organização do Estado (organização político-administrativa, União, Estados Federados, Municípios, Distrito Federal e Territórios, militares dos Estados, Distrito Federal e Territórios). 1.3. Da organização dos poderes (poder legislativo, congresso nacional, atribuições do congresso nacional, câmara dos deputados, senado federal, deputados e senadores, processo legislativo, poder executivo). 1.4. Da defesa do Estado e das Instituições Democráticas (estado de defesa e estado de sítio, Forças Armadas, segurança pública). 1.5. Da administração pública.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Processual Penal', '1. Aplicação da lei processual no tempo, no espaço e em relação às pessoas. 1.1. Disposições preliminares do Código de Processo Penal. 2. Inquérito policial. 3. Ação penal. 4. Prisão, medidas cautelares e liberdade provisória. 4.1. Lei federal nº 7.960/1989 (prisão temporária). 5. Processo e julgamento dos crimes de responsabilidade dos funcionários públicos. 6. O habeas corpus e seu processo. 7. Jurisdição e competência. 8. Das questões e processos incidentes. 9. Da prova. 10. Do processo comum. 11. Das nulidades e dos recursos.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Administrativo', '1. Estado, governo e administração pública: conceitos, elementos, poderes e organização; natureza, fins e princípios. 2. Organização administrativa do Estado; administração direta e indireta. 3. Agentes públicos: espécies e classificação; poderes, deveres e prerrogativas; cargo, emprego e função públicos; regime jurídico único: provimento, vacância, remoção, redistribuição e substituição; direitos e vantagens; regime disciplinar; responsabilidade civil, criminal e administrativa. 4. Poderes administrativos: poder hierárquico; poder disciplinar; poder regulamentar; poder de polícia; uso e abuso do poder. 5. Atos administrativos: conceitos, requisitos, atributos, classificação, espécies e invalidação. 6. Controle e responsabilização da administração: controle administrativo; controle judicial; controle legislativo; responsabilidade civil do Estado. 7. Lei federal nº 8.429/1992 (Dispõe sobre as sanções aplicáveis em virtude da prática de atos de improbidade administrativa). 8. Leis de licitação 8.666/93 e 14.133/2021. 9. Lei Estadual nº 13.800 (Regula o processo administrativo no âmbito da Administração Pública do Estado de Goiás).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Penal Militar', '1. Decreto-Lei 1.001/69. 1.1. Aplicação da lei penal militar. 1.2. Do Crime. 1.3. Da Imputabilidade Penal. 1.4. Concurso de agentes. 1.5. Das penas principais. 1.6. Das Penas acessórias. 1.7. Efeitos da condenação. 1.8. Ação penal. 1.9. Extinção da punibilidade. 1.10. Dos crimes militares em tempo de paz (arts. 136 ao 354). 1.11. Dos crimes contra a autoridade ou disciplina militar. 1.12. Dos crimes contra o serviço e o dever militar. 1.13. Dos crimes contra a Administração Militar. 1.11. Dos crimes militares em tempo de guerra (arts. 355 ao 408).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Direito Processual Penal Militar', 'Decreto-Lei 1002/69. Da Lei processual penal militar e sua aplicação. Da polícia judiciária militar. Da ação penal militar. Do juiz, auxiliares e partes no processo. Da denúncia. Do foro militar. Da competência, desaforamento e dos conflitos de competência. Das questões prejudiciais. Dos incidentes. Das medidas preventivas e assecuratórias. Das comunicações processuais. Das provas. Dos processos. Das nulidades e dos recursos. Da execução. Da justiça militar em tempo de Guerra. Do inquérito policial militar.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
  ('pm-go-soldado', 'Legislação Penal Especial', '1. Tráfico ilícito e uso indevido de drogas (Lei nº 11.343/2006). 2. Crimes hediondos (Lei nº 8.072/1990).3. Crimes resultantes de preconceitos de raça ou de cor (Lei nº 7.716/1989). 4. Abuso de Autoridade (Lei nº 13.869/2019). 5. Crimes de tortura (Lei nº 9.455/1997). 6. Estatuto da Criança e do Adolescente (Lei nº 8.069/1990). 7. Estatuto do desarmamento (Lei nº 10.826/2003). 8. Crimes previstos no Código de proteção e defesa do consumidor (Lei nº 8.078/1990). 9. Crimes contra o meio ambiente (Lei nº 9.605/1998). 10. Juizados especiais (Lei nº 9.099/1995 e Lei nº 10.259/2001). 11. Crimes previstos no Código de Trânsito Brasileiro (Lei nº 9.503/1997). 12. Interceptação telefônica (Lei nº 9.296/1996). 13. Lei nº 12.850/2013. 14. Pacote Anticrime (Lei nº 13.964/2019).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-fd3.pdf'),
