  ('pm-go-oficial', 'Direito Constitucional', '1. Direito Constitucional. 1.1. Poder constituinte. 1.2. Natureza. 1.3. Poder constituinte originário. 1.4. Poder constituinte derivado. 1.5. Limites ao poder de reforma da Constituição. 1.6. Conceito e Espécies. 1.7. Cláusulas pétreas. 1.8. Normas constitucionais. 1.9. Classificação. 1.10. Interpretação, integração e aplicação. 1.11. Controle da constitucionalidade. 1.12. Via de ação e via de exceção. 1.13. Controle de constitucionalidade por omissão. 1.14. Recepção. 1.15. Repristinação. 1.16. Princípios fundamentais da Constituição (arts. 1º a 4º). 1.17. Direitos e deveres individuais e coletivos (art. 5º). 1.18. Direitos sociais. 1.19. Nacionalidade. 1.20. Direitos políticos (arts. 6º a 16º). 1.21. Organização do Estado. 1.22. Organização administrativa. 1.23. União. Estados. 1.24. Distrito Federal. 1.25. Municípios. 1.26. Intervenção nos Estados e Municípios (arts. 18 a 36). 1.27. Da Organização dos Poderes. 1.28. Poder Legislativo. 1.29. Estrutura e competência (arts. 44 a 52 e 59 a 69). 1.30. Poder Executivo. 1.31. Estrutura e competência (arts. 76 a 86). 1.32. Poder Judiciário. 1.33. Estrutura e competência (arts. 92 a 125). 1.34. Das funções essenciais à Justiça: Ministério Público (arts. 127 a 132). 1.35. Advocacia e Defensoria Pública (arts. 133 a 135). 1.36. Da ordem econômica e financeira: Princípios gerais (arts. 170 a 181). 1.37. Política agrícola e fundiária e reforma agrária (arts. 184 a 191). 1.38. Sistema financeiro nacional (art. 192). 1.39. Ordem social: Saúde (arts. 196 a 200). 1.40. Comunicação social (arts. 220 a 224). 1.41. Meio ambiente (art. 225). 1.42. Família: Criança, adolescente e idosos (arts. 226 a 230). 1.43. Constituição do Estado de Goiás - Da Organização dos Poderes, Estruturas e Competência.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf'),
  ('pm-go-oficial', 'Direito Processual Penal', '1. Direito Processual Penal: Aplicação da lei processual no tempo, no espaço e em relação às pessoas. 1.1. Disposições preliminares do Código de Processo Penal. 2. Inquérito policial (arts. 4º a 23 do C.P.P.). 3. Ação penal (arts. 24 a 62 do C.P.P.). 4. Competência (arts. 69 a 91 do C.P.P.). 5. Questões e Processos Incidentes (arts. 92 a 154 do C.P.P.). 6. Prova (arts. 155 a 250 do C.P.P.). 7. Do Juiz, do Ministério Público, do Acusado e Defensor, dos Assistentes e Auxiliares da Justiça (arts. 251 a 281 do C.P.P.). 8. Prisão e Liberdade Provisória (arts. 282 a 350 do C.P.P.). 9. Citações e Intimações (arts. 351 a 372 do C.P.P.). 10. Sentença (arts. 381 a 393 do C.P.P.). 11. Processos em Espécie (arts. 394 a 555 do C.P.P.). 12. Nulidades (arts. 563 a 573 do C.P.P.). 13. Recursos (arts. 574 a 620 do C.P.P.). 14. Revisão Criminal (arts. 621 a 631 do C.P.P.). 15. Habeas Corpus (arts. 647 a 667 do C.P.P.) e Mandado de Segurança em Matéria Penal. 16. Lei 7.210/84 (Execução Penal). 17. Lei 11.340/2006 (violência familiar e doméstica contra a mulher). 18. Lei nº 9.099/95 e 10.259/2001, com as alterações das Leis 9.839/99, 10.455/02 e 11.313/06 (Juizados Especiais Criminais). 19. Lei federal nº 7.960/1989 (prisão temporária).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf'),
  ('pm-go-oficial', 'Direito Administrativo', '1. Administração Pública: conceito, elementos, natureza e objetivos. Organização Administrativa do Estado: Administração direta e indireta; Agentes Públicos: espécie e classificação, poderes, deveres e prerrogativas; cargo, emprego. 2. Atividade administrativa: abuso e desvio de poder, desvio de finalidade. 3. Administração Pública: princípios da legalidade, moralidade, impessoalidade, proporcionalidade, eficiência, continuidade e autoexecutoriedade. 4. Os poderes administrativos: regulamentar, hierárquico, disciplinar e de polícia. 5. A discricionariedade, conteúdo e limites. 6. Autarquias, fundações, empresas públicas e sociedades de economia mista. 7. A privatização, disciplina e efeitos. O serviço público: concessão, autorização e permissão. 8. Agências reguladoras. 9. Ato administrativo: conceitos, requisitos, atributos, classificação, espécie e invalidação 10. Condições e pressupostos. 11. Vícios. 12. Formas de desconstituição, revogação e anulação. 13. Contrato administrativo: características, formalização, execução, inexecução e principais tipos. 14. Formas de rescisão e revisão. 15. Equilíbrio contratual e cláusulas exorbitantes. 16. Leis de licitação 8.666/93 e 14.133/2021. 17. Dispensa e inexigibilidade. 18. O procedimento licitatório. 19. Direito de propriedade e limitações administrativas. 20. A desapropriação e seu processo. 21. Requisição, servidão e ocupação provisória. 22. O controle da Administração e suas modalidades. 23. Mandado de segurança, ação popular e ação civil pública. 24. A responsabilidade civil do Estado pelos atos executivos, legislativos e jurisdicionais. 25. O processo administrativo, finalidades, garantias e tipos. Lei Estadual nº 13.800 (Regula o processo administrativo no âmbito da Administração Pública do Estado de Goiás). 26. Servidores públicos: direitos, deveres e responsabilidades. 27. Lei nº 8.429/1992 ­ Dispõe sobre as sanções aplicáveis em virtude da prática de atos de improbidade administrativa.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf'),
  ('pm-go-oficial', 'Direito Penal Militar', '1. Decreto-Lei 1.001/69. 1.1. Da aplicação da Lei penal militar. 1.2. Do crime. 1.3. Da imputabilidade penal. 1.4. Do concurso de agentes. 1.5. Das penas. 1.6. Efeitos da condenação. 1.7. Das medidas de segurança. 1.8. Da ação penal. 1.9. Da extinção da punibilidade. 1.10. Dos crimes militares em tempo de paz (arts. 136 ao 354). 1.11. Dos crimes militares em tempo de guerra (arts. 355 ao 408). Dos crimes contra a administração militar.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf'),
  ('pm-go-oficial', 'Direito Processual Penal Militar', '1. Decreto-Lei 1.002/69. 1.1. Da Lei processual penal militar e sua aplicação. 1.2. Da polícia judiciária militar. 1.3. Da ação penal militar. 1.4. Do juiz, auxiliares e partes no processo. 1.5. Da denúncia. 1.6. Do foro militar. 1.7. Da competência, desaforamento e dos conflitos de competência. 1.8. Das questões prejudiciais. 1.9. Dos incidentes. 1.10. Dos crimes contra a autoridade ou disciplina militar. 1.11. Dos crimes contra o serviço e o dever militar. 1.12. Das medidas preventivas e assecuratórias. 1.13. Dos processos. 1.14. Das nulidades e dos recursos. 1.15. Da execução. 1.16. Da justiça militar em tempo de Guerra. 1.17. Do Inquérito Policial Militar. 1.18. Da citação, intimação e notificação. 1.19. Dos atos probatórios.', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf'),
  ('pm-go-oficial', 'Legislação Penal Especial', '1. Estatuto do Desarmamento (Lei nº 10.826/03). 2. Crimes hediondos (Lei nº 8.072/90). 3. Crimes resultantes de preconceitos de raça ou de cor (Lei nº 7.716/89). 4. Apresentação e uso de documento de identificação pessoal (Lei nº 5.553/68). 5. Lei 13. 869/2019- Dispõe sobre os crimes de abuso de autoridade. 6. Definição dos crimes de tortura (Lei nº 9.455/97). 7. Estatuto da Criança e do Adolescente (Lei nº 8.069/90). 8. Estatuto do Idoso (Lei nº 10.741/03): dos crimes em espécies. 9. Código de Trânsito Brasileiro (Lei nº 9.503/97).10. Lei Maria da Penha ­ Violência doméstica e familiar contra a mulher (Lei nº 11.340/06): Título I e II, Cap. III do Título III. 11. Sistema Nacional de Políticas Públicas sobre Drogas (Lei nº 11.343/06). 12. Crimes contra as Relações de Consumo (Título II da Lei nº 8.078/90). 13. Lei das Contravenções Penais (Decreto-Lei nº 3.688/41). 14. Lei dos Crimes contra o Meio Ambiente (Lei nº 9.605/98). 15. Estatuto dos Policiais Militares do Estado de Goiás (Lei Estadual n.º 8.033/75).', 'https://goias.gov.br/administracao/wp-content/uploads/sites/27/2022/04/120522-AnexoIIRetificado-88e.pdf')
) as v(slug, materia, texto, fonte_url)
join public.editais_catalog e on e.slug = v.slug
join public.subjects_catalog s on s.name = v.materia
on conflict (edital_catalog_id, subject_catalog_id) do update
  set texto = excluded.texto, fonte_url = excluded.fonte_url, conferido_em = excluded.conferido_em;

-- Verificação dura: 24 seções (9+6+9) e nenhum programa de matéria que o
-- edital não tenha na grade.
do $$
declare v int;
begin
  select count(*) into v from public.edital_programas;
  if v <> 24 then raise exception 'edital_programas: esperado 24, achei %', v; end if;
  select count(*) into v from public.edital_programas p
  where not exists (
    select 1 from public.edital_catalog_subjects ecs
    where ecs.edital_catalog_id = p.edital_catalog_id
      and ecs.subject_catalog_id = p.subject_catalog_id
  );
  if v > 0 then raise exception 'programa órfão (matéria fora da grade): %', v; end if;
end $$;
